BEGIN;
ALTER TABLE public.redirect_domain_preferences DROP CONSTRAINT redirect_domain_preferences_pending_tenant_fence;
ALTER TABLE public.redirect_qr_styles DROP CONSTRAINT redirect_qr_styles_pending_tenant_fence;
ALTER TABLE public.redirect_qr_assets DROP CONSTRAINT redirect_qr_assets_pending_tenant_fence;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();other uuid:=gen_random_uuid();legacy uuid:='58aa4340-8f21-4b7f-9a10-90be2da89c01';foreign_asset uuid:=gen_random_uuid();asset uuid;own_version uuid;image uuid;root uuid;snapshot jsonb;result jsonb;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor);INSERT INTO public.user_roles VALUES(actor,'admin');
 INSERT INTO public.redirect_workspaces(id,name,slug) VALUES(other,'QR defaults fixture','qr-defaults-fixture');
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) VALUES(other,actor);
 INSERT INTO public.redirect_domain_preferences(workspace_id,singleton) VALUES(other,true);
 INSERT INTO public.redirect_qr_assets(id,workspace_id,target_scope,requested_by,mime,bytes,width,height,sha256,state) VALUES(foreign_asset,other,'workspace',actor,'image/png',8,1,1,repeat('b',64),'active');
 INSERT INTO public.redirect_qr_styles(workspace_id,scope,style,logo_mode,logo_asset_id) VALUES(other,'workspace','{"dots":"circle"}','custom',foreign_asset);
 snapshot:=jsonb_build_object('preference',(SELECT to_jsonb(p) FROM public.redirect_domain_preferences p WHERE workspace_id=other),'style',(SELECT to_jsonb(s) FROM public.redirect_qr_styles s WHERE workspace_id=other),'asset',(SELECT to_jsonb(a) FROM public.redirect_qr_assets a WHERE id=foreign_asset));
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-session-actor',actor)::text,true);
 result:=public.redirect_qr_style_resource(actor,p_values=>'{"version":null,"style":{"dots":"joined"}}');own_version:=(result->>'version')::uuid;
 IF result#>>'{effectiveStyle,dots}'<>'joined' OR result->'effectiveLogo'<>'null'::jsonb THEN RAISE EXCEPTION 'Workspace default inherited foreign appearance';END IF;
 result:=public.reserve_redirect_qr_logo(actor,NULL,own_version,'image/png',8,1,1,repeat('c',64));asset:=(result->>'id')::uuid;
 result:=public.finish_redirect_qr_logo(actor,asset);
 IF result#>>'{effectiveLogo,id}'<>asset::text OR result#>>'{effectiveStyle,dots}'<>'joined' THEN RAISE EXCEPTION 'Local logo finish conflicted with foreign workspace';END IF;
 DELETE FROM public.redirect_domain_preferences WHERE workspace_id=legacy;
 result:=public.redirect_domain_preference(actor);
 IF result->>'version' IS NOT NULL OR result->>'domainId' IS NOT NULL THEN RAISE EXCEPTION 'Missing preference inherited foreign row';END IF;
 result:=public.redirect_domain_preference(actor,'{"version":null,"domainId":null}');
 IF result->>'version' IS NULL OR result->>'ready'<>'true' THEN RAISE EXCEPTION 'Workspace preference did not initialize';END IF;
 BEGIN PERFORM public.redirect_domain_preference(actor,'{"version":null,"domainId":null}');RAISE EXCEPTION 'Stale preference initialization accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 result:=public.redirect_qr_image_resource('create',actor,p_values=>'{"url":"https://example.org/authoritative-style"}',p_hash=>repeat('a',64));image:=(result->>'id')::uuid;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','qr-defaults-public','https://example.org/local') RETURNING id INTO root;
 PERFORM public.redirect_qr_image_resource('create',actor,p_values=>jsonb_build_object('linkId',root),p_hash=>repeat('d',64));
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',other)::text,true);
 result:=public.redirect_public_qr_image(repeat('a',64));
 IF result#>>'{style,dots}'<>'joined' OR result#>>'{effectiveLogo,id}'<>asset::text THEN RAISE EXCEPTION 'Public QR styling followed caller workspace header';END IF;
 result:=public.redirect_public_qr_image(repeat('d',64));
 IF result->>'url'<>'https://queer.guide/go/qr-defaults-public' OR result#>>'{effectiveLogo,id}'<>asset::text THEN RAISE EXCEPTION 'Public managed QR URL or branding followed private request context';END IF;
 IF redirect_internal.qr_style_for_workspace(other,NULL)->>'dots'<>'circle' OR redirect_internal.qr_logo_for_workspace(other,NULL)#>>'{effectiveLogo,id}'<>foreign_asset::text THEN RAISE EXCEPTION 'Internal authoritative style helper lost row workspace';END IF;
 BEGIN PERFORM public.redirect_qr_effective_style();RAISE EXCEPTION 'Private style accepted inactive workspace';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF has_function_privilege('anon','redirect_internal.qr_style_for_workspace(uuid,uuid)','execute') OR has_function_privilege('authenticated','redirect_internal.qr_logo_for_workspace(uuid,uuid)','execute') THEN RAISE EXCEPTION 'Private style helper exposed';END IF;
 IF jsonb_build_object('preference',(SELECT to_jsonb(p) FROM public.redirect_domain_preferences p WHERE workspace_id=other),'style',(SELECT to_jsonb(s) FROM public.redirect_qr_styles s WHERE workspace_id=other),'asset',(SELECT to_jsonb(a) FROM public.redirect_qr_assets a WHERE id=foreign_asset))<>snapshot THEN RAISE EXCEPTION 'Local defaults changed foreign workspace';END IF;
END $$;
ROLLBACK;
